function explainerPreview(id,settings={},size=256){const c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d');ctx.scale(size/240,size/240);drawExplainerVector(ctx,id,settings,0);return c.toDataURL('image/png')}
function explainerMeta(o){return o?.type==='image'&&o.explainerAsset&&explainerObjects.some(a=>a.id===o.explainerAsset.id)?o.explainerAsset:null}
function explainerStyleChoices(id){return explainerRasterIds.has(id)?Object.keys(explainerStyles):['vector']}
async function explainerSource(id,style,settings){if(style==='vector')return explainerPreview(id,settings,640);const r=await fetch('assets/explainers/'+style+'-'+id+'.png');if(!r.ok)throw Error('This object artwork could not load.');return dataURL(new Blob([await r.arrayBuffer()],{type:'image/png'}))}
const propBeforeExplainers=prop;prop=function(c,o,v){const a=explainerMeta(o);if(!a||a.style!=='vector')return propBeforeExplainers(c,o,v);c.save();c.translate(v.x,v.y);c.rotate(v.rotation*Math.PI/180);c.scale(v.scale*160/240,v.scale*160/240);c.translate(-120,-120);c.globalAlpha=v.opacity;drawExplainerVector(c,a.id,a,Math.max(0,time-clipStart(o)));c.restore()};
const stateBeforeExplainers=stateAt;stateAt=function(o,t){const v=stateBeforeExplainers(o,t),a=explainerMeta(o);if(!a)return v;const elapsed=Math.max(0,t-clipStart(o))*(a.speed||1);if(a.motion==='float')v.y+=Math.sin(elapsed*2.4)*7;if(a.motion==='pulse')v.scale*=1+.045*Math.sin(elapsed*3);if(a.motion==='pop'){const f=clamp(elapsed/.6,0,1);v.scale*=Math.max(.01,1-Math.pow(1-f,3));v.opacity*=clamp(elapsed/.25,0,1)}return v};
const rawBeforeExplainers=rawStateAt;rawStateAt=function(o,t){return rawBeforeExplainers({...o,explainerAsset:undefined},t)};
$('propsTab').insertAdjacentHTML('afterbegin','<section class="explainer-library-entry"><div class="eyebrow">EXPLAINER COLLECTION</div><h3>Objects for every idea.</h3><div id="explainerStyleSamples"></div><button id="openExplainerAssets" class="primary">Browse 28 objects</button><p class="note">2D illustration · clay · realistic</p></section>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="explainerAssetsDialog"><div class="tool-heading"><div><div class="eyebrow">BUILT FOR YOUR STORIES</div><h2>Explainer objects</h2></div><button id="closeExplainerAssets">Done</button></div><div class="explainer-asset-filters"><input id="explainerAssetSearch" type="search" aria-label="Search explainer objects" placeholder="Find a laptop, book, idea…"><select id="explainerAssetStyle" aria-label="Drawing style"><option value="all">All styles</option>${Object.entries(explainerStyles).map(([id,name])=>'<option value="'+id+'">'+name+'</option>').join('')}</select><select id="explainerAssetCategory" aria-label="Object theme"><option value="all">All themes</option>${[...new Set(explainerObjects.map(o=>o.category))].map(c=>'<option>'+c+'</option>').join('')}</select></div><p id="explainerAssetStatus" class="note" role="status">Pick an object to add it. Movement, colors and detail animation are in its inspector.</p><div id="explainerAssetGrid"></div><p class="note">24 original vector illustrations, plus laptop and phone cut-outs in clay and realistic styles. Cut-outs animate as flat artwork. Vector detail animations include chart growth, gear rotation, steam and typing dots.</p></dialog>`);
let explainerInsertBusy=false;const explainerThumbs=new Map();
function explainerThumbnail(id){if(!explainerThumbs.has(id))explainerThumbs.set(id,explainerPreview(id));return explainerThumbs.get(id)}
function renderExplainerAssets(){const search=$('explainerAssetSearch').value.trim().toLowerCase(),style=$('explainerAssetStyle').value,category=$('explainerAssetCategory').value,grid=$('explainerAssetGrid');grid.replaceChildren();for(const item of explainerObjects){if(category!=='all'&&item.category!==category||search&&![item.name,item.category,item.detail].join(' ').toLowerCase().includes(search))continue;for(const kind of explainerStyleChoices(item.id)){if(style!=='all'&&style!==kind)continue;const b=document.createElement('button');b.className='explainer-asset-card';b.setAttribute('aria-label','Add '+item.name+' · '+explainerStyles[kind]);const img=document.createElement('img');img.src=kind==='vector'?explainerThumbnail(item.id):'assets/explainers/'+kind+'-'+item.id+'.png';img.alt='';img.loading='lazy';const name=document.createElement('strong');name.textContent=item.name;const tag=document.createElement('small');tag.textContent=explainerStyles[kind];b.append(img,name,tag);b.onclick=()=>addExplainerAsset(item.id,kind);grid.append(b)}}if(!grid.children.length)grid.innerHTML='<p class="note">No objects match. Try another theme or style.</p>'}
async function addExplainerAsset(id,style='vector'){if(explainerInsertBusy||recording)return;const sceneAtStart=current(),projectAtStart=project,item=explainerObjects.find(a=>a.id===id);if(!item||!explainerStyleChoices(id).includes(style))return;if(sceneAtStart.objects.length>=499)return toast('Keep fewer than 500 layers in a scene.');explainerInsertBusy=true;window.editorTaskBusy=true;try{const settings={...explainerOptions,id,style,details:style==='vector'},src=await explainerSource(id,style,settings);await imageReady(src);if(current()!==sceneAtStart||project!==projectAtStart)throw Error('The scene changed. Add the object again.');newObject('image',{name:item.name,src,explainerAsset:settings});$('explainerAssetsDialog').close();toast(item.name+' added. Choose movement in the inspector.')}catch(e){$('explainerAssetStatus').textContent=e.message;toast(e.message)}finally{explainerInsertBusy=false;window.editorTaskBusy=false}}
$('openExplainerAssets').onclick=()=>{stop();renderExplainerAssets();$('explainerAssetsDialog').showModal()};$('closeExplainerAssets').onclick=()=>$('explainerAssetsDialog').close();$('explainerAssetSearch').oninput=renderExplainerAssets;$('explainerAssetStyle').onchange=renderExplainerAssets;$('explainerAssetCategory').onchange=renderExplainerAssets;
for(const [i,style]of Object.keys(explainerStyles).entries()){const img=document.createElement('img');img.src=style==='vector'?explainerThumbnail('laptop'):'assets/explainers/'+style+'-laptop.png';img.alt=explainerStyles[style];$('explainerStyleSamples').append(img)}
const controlsBeforeExplainers=renderControls;renderControls=function(){controlsBeforeExplainers();const o=object(),a=explainerMeta(o);if(!a)return;const item=explainerObjects.find(i=>i.id===a.id),panel=document.createElement('details');panel.open=true;panel.innerHTML='<summary>Explainer object</summary><label>Style<select id="explainerObjectStyle">'+explainerStyleChoices(a.id).map(id=>'<option value="'+id+'">'+explainerStyles[id]+'</option>').join('')+'</select></label><label>Movement<select id="explainerObjectMotion"><option value="still">Still</option><option value="float">Gentle float</option><option value="pop">Pop in</option><option value="pulse">Pulse</option></select></label><label>Speed<input id="explainerObjectSpeed" type="range" min="0.25" max="3" step="0.05"></label>'+(a.style==='vector'?'<label>Primary<input id="explainerObjectPrimary" type="color"></label><label>Accent<input id="explainerObjectAccent" type="color"></label><label>'+esc(item.detail)+'<input id="explainerObjectDetails" type="checkbox"></label>':'<p class="note">Transparent artwork. Use pose keys or movement presets to animate this cut-out.</p>');$('controls').prepend(panel);$('explainerObjectStyle').value=a.style;$('explainerObjectMotion').value=a.motion;$('explainerObjectSpeed').value=a.speed;const update=async()=>{try{const src=await explainerSource(a.id,a.style,a);if(!project.scenes.some(s=>s.objects.includes(o)))return;o.src=src;await imageReady(src);save();render()}catch(e){toast(e.message)}};$('explainerObjectStyle').onchange=async e=>{if(o.locked)return;const candidate={...a,style:e.target.value,details:e.target.value==='vector'};e.target.disabled=true;try{const src=await explainerSource(a.id,candidate.style,candidate);await imageReady(src);if(!project.scenes.some(s=>s.objects.includes(o)))return;Object.assign(a,candidate);o.src=src;save();render()}catch(error){toast(error.message);render()}};$('explainerObjectMotion').onchange=e=>{if(o.locked)return;a.motion=e.target.value;save();draw()};$('explainerObjectSpeed').onchange=e=>{if(o.locked)return;a.speed=+e.target.value;save();draw()};if(a.style==='vector'){for(const[key,id]of[['primary','explainerObjectPrimary'],['accent','explainerObjectAccent']]){$(id).value=a[key];$(id).oninput=e=>{if(o.locked)return;a[key]=e.target.value;draw()};$(id).onchange=update}$('explainerObjectDetails').checked=a.details;$('explainerObjectDetails').onchange=e=>{if(o.locked)return;a.details=e.target.checked;update()}}panel.querySelectorAll('input,select,button').forEach(e=>e.disabled=!!o.locked)};
const validateBeforeExplainers=valid;valid=function(p){return validateBeforeExplainers(p)&&p.scenes.every(s=>s.objects.every(o=>!o.explainerAsset||o.type==='image'&&explainerObjects.some(a=>a.id===o.explainerAsset.id)&&explainerStyleChoices(o.explainerAsset.id).includes(o.explainerAsset.style)&&['still','float','pop','pulse'].includes(o.explainerAsset.motion)&&typeof o.explainerAsset.details==='boolean'&&['primary','accent'].every(k=>/^#[0-9a-f]{6}$/i.test(o.explainerAsset[k]))&&Number.isFinite(o.explainerAsset.speed)&&o.explainerAsset.speed>=.25&&o.explainerAsset.speed<=3))};
render();
